command:
// ==========================================
// LUNAS WIRKUNG: KALTES STARREN (RONDRA)
//
// - Spieler markiert alle infrage kommenden Ziele
// - Zielkategorie: Erwachte, Tiere
// - Reichweite: 8 Schritt
// - GM wählt genau ein gespeichertes Ziel
// - kein erneutes Target durch den GM
// - Wirkender erhält Kaltes Starren
// - Ziel erhält exakt QS Stufen Furcht
// - Dauer: QS × 4 Kampfrunden
// - gekoppelte Effekte + Cleanup
// - keine doppelte Furchtzählung
// - Effekte über Block 6
// - Wirkungsende über Block 7
// - eine öffentliche Karte + „Effekt anwenden“
// ==========================================


// +++ 0 - GEKOPPELTES CLEANUP ++++++++++++++++++++++++++++++++

if (globalThis._dskKaltesStarrenCleanupHookId) {
    Hooks.off("deleteActiveEffect", globalThis._dskKaltesStarrenCleanupHookId);
}

globalThis._dskKaltesStarrenCleanupAktiv ||= new Set();

globalThis._dskKaltesStarrenCleanupHookId = Hooks.on("deleteActiveEffect", async effect => {
    if (effect.getFlag("dsk", "isKaltesStarrenQuelle") !== true) return;

    const aktiveGMs = game.users.filter(user => user.isGM && user.active)
        .sort((a, b) => String(a.id).localeCompare(String(b.id)));
    const zustaendigerGM = aktiveGMs[0] || null;

    if (zustaendigerGM && game.user.id !== zustaendigerGM.id) return;
    if (!zustaendigerGM && !game.user.isGM) return;

    const linkId = effect.getFlag("dsk", "kaltesStarrenLinkId");
    if (!linkId || globalThis._dskKaltesStarrenCleanupAktiv.has(linkId)) return;

    globalThis._dskKaltesStarrenCleanupAktiv.add(linkId);

    try {
        const zielEffektUuid = effect.getFlag("dsk", "zielEffektUuid");
        const zielActorUuid = effect.getFlag("dsk", "zielActorUuid");
        let geloescht = false;

        if (zielEffektUuid) {
            try {
                const zielEffekt = await fromUuid(zielEffektUuid);

                if (
                    zielEffekt?.documentName === "ActiveEffect" &&
                    zielEffekt.getFlag("dsk", "kaltesStarrenLinkId") === linkId
                ) {
                    await zielEffekt.delete({ dskKaltesStarrenEnde: true });
                    geloescht = true;
                }
            } catch (error) {
                console.warn("Kaltes Starren: Zieleffekt konnte nicht über UUID gelöscht werden.", {
                    zielEffektUuid,
                    error
                });
            }
        }

        if (!geloescht && zielActorUuid) {
            try {
                const doc = await fromUuid(zielActorUuid);
                const zielActor = doc?.documentName === "Token" ? doc.actor : doc;

                const zielEffekte = zielActor?.effects?.filter(zielEffekt =>
                    zielEffekt.getFlag("dsk", "isKaltesStarrenZiel") === true &&
                    zielEffekt.getFlag("dsk", "kaltesStarrenLinkId") === linkId
                ) || [];

                if (zielEffekte.length) {
                    await zielActor.deleteEmbeddedDocuments(
                        "ActiveEffect",
                        zielEffekte.map(zielEffekt => zielEffekt.id),
                        { dskKaltesStarrenEnde: true }
                    );
                }
            } catch (error) {
                console.warn("Kaltes Starren: Gekoppeltes Cleanup fehlgeschlagen.", {
                    zielActorUuid,
                    error
                });
            }
        }
    } finally {
        setTimeout(() => globalThis._dskKaltesStarrenCleanupAktiv.delete(linkId), 500);
    }
});


// +++ 1 - INIT-MODUS ++++++++++++++++++++++++++++++++++++++++++

if (typeof args !== "undefined" && args[0] === "WeckerAufruf") {
    globalThis._dskKaltesStarrenInit = true;
    return;
}


// +++ 2 - NORMALE AUSFÜHRUNG ++++++++++++++++++++++++++++++++++

(async function () {
const macroUuid = this?.uuid || null;

// +++ 3 - FRAMEWORK +++++++++++++++++++++++++++++++++++++++++++

const frameworkUuid = "Compendium.dsk-havena-und-umland.makros.Macro.fHQ2OuDo3Fe3spBn";
const frameworkFehlt =
    !globalThis.DSK?.Effekt?.Anwenden ||
    !globalThis.DSK?.EffektEnde?.Register ||
    !globalThis.DSK?.QS?.Ermitteln ||
    !globalThis.DSK?.Token?.Finde ||
    !globalThis.DSK?.Target?.Merken ||
    !globalThis.DSK?.Target?.Finden ||
    !globalThis.DSK?.Target?.Actor ||
    !globalThis.DSK?.Wesen?.match ||
    !globalThis.DSK?.Geometrie?.Distanz ||
    !globalThis.DSK?.GMAnfrage?.Speichern ||
    !globalThis.DSK?.GMAnfrage?.Finden ||
    !globalThis.DSK?.GMAnfrage?.Lesen ||
    !globalThis.DSK?.GMAnfrage?.Loeschen ||
    !globalThis.DSK?.GabenUI?.GMMakroButton ||
    !globalThis.DSK?.GabenUI?.AnfrageKarteErstellen ||
    !globalThis.DSK?.GabenUI?.AnfrageKarteAktualisieren;

if (frameworkFehlt) {
    const fwMacro = await fromUuid(frameworkUuid);

    if (!fwMacro?.execute) {
        return ui.notifications.error(
            "Luna sagt 🌙: Das DSK-Framework wurde nicht gefunden!"
        );
    }

    await fwMacro.execute();
    await new Promise(resolve => setTimeout(resolve, 150));
}

const DSK_FW = globalThis.DSK;

if (
    !DSK_FW?.Effekt?.Anwenden ||
    !DSK_FW?.EffektEnde?.Register ||
    !DSK_FW?.QS?.Ermitteln ||
    !DSK_FW?.Token?.Finde ||
    !DSK_FW?.Target?.Merken ||
    !DSK_FW?.Target?.Finden ||
    !DSK_FW?.Target?.Actor ||
    !DSK_FW?.Wesen?.match ||
    !DSK_FW?.Geometrie?.Distanz ||
    !DSK_FW?.GMAnfrage?.Speichern ||
    !DSK_FW?.GMAnfrage?.Finden ||
    !DSK_FW?.GMAnfrage?.Lesen ||
    !DSK_FW?.GMAnfrage?.Loeschen ||
    !DSK_FW?.GabenUI?.GMMakroButton ||
    !DSK_FW?.GabenUI?.AnfrageKarteErstellen ||
    !DSK_FW?.GabenUI?.AnfrageKarteAktualisieren
) {
    return ui.notifications.error(
        "Luna sagt 🌙: Das DSK-Framework 01.02 wurde nicht vollständig geladen!"
    );
}

// +++ 4 - GRUNDDATEN ++++++++++++++++++++++++++++++++++++++++++

const gabenName = "Kaltes Starren", vollerName = "Kaltes Starren (Rondra)", ahne = "Rondra";
const flagKey = "pendingKaltesStarrenRondra", endeKey = "rondraKaltesStarren";
const reichweite = 8;
const endeText = "Der eisige Blick des Rondrakindes normalisiert sich wieder. Die ausgelöste Furcht endet.";

DSK_FW.EffektEnde.Register(endeKey, vollerName, endeText);

// +++ 5 - HELFER ++++++++++++++++++++++++++++++++++++++++++++++

const raeumeQSAuf = async actor => {
    if (actor?.getFlag("world", "letzteGabenQS") !== undefined) {
        await actor.unsetFlag("world", "letzteGabenQS");
    }
    if (actor?.getFlag("world", "letzteGabenMessageId") !== undefined) {
        await actor.unsetFlag("world", "letzteGabenMessageId");
    }
};

const istGueltigesZiel = actor =>
    DSK_FW.Wesen.match(actor, [
        "erwacht", "erwachter", "erwachte", "tier", "tiere"
    ]);

const ladeZiel = async daten => {
    if (!daten) return { token: null, actor: null };
    const token = await DSK_FW.Target.Finden(daten);
    return { token, actor: token?.actor || await DSK_FW.Target.Actor(daten) };
};

const beschreibungFuer = (casterName, qs) =>
    `Der Blick von <b>${casterName}</b> wird kalt wie Eis.` +
    `<br><br>Das erste Ziel <i>(Erwachte oder Tiere)</i> innerhalb von <b>${reichweite} Schritt</b>, ` +
    `das mindestens eine Aktion lang angestarrt wird, erleidet <b>${qs} Stufe(n) Furcht</b>.` +
    `<br><br>Die Furcht bleibt bis zum Ende der Wirkungsdauer bestehen.`;

// +++ 6 - GM WÄHLT AUS GESPEICHERTEN ZIELEN ++++++++++++++++++

const frageZielAuswahl = async ({ ziele, casterName, qs }) => {
    const eintraege = [];

    for (let index = 0; index < ziele.length; index++) {
        const daten = ziele[index];
        const { token, actor } = await ladeZiel(daten);
        if (!actor) continue;

        eintraege.push({
            index,
            name: daten.name || token?.name || actor.name
        });
    }

    if (!eintraege.length) return null;
    if (eintraege.length === 1) return eintraege[0].index;

    const auswahlHtml = eintraege.map((eintrag, index) =>
        `<label style="display:flex;gap:7px;align-items:center;margin-bottom:6px;padding:6px 8px;background:rgba(255,255,255,.35);border-radius:4px;cursor:pointer;">
            <input type="radio" name="ziel" value="${eintrag.index}" ${index === 0 ? "checked" : ""}>
            <span><b>${eintrag.name}</b></span>
        </label>`
    ).join("");

    return foundry.applications.api.DialogV2.wait({
        window: { title: vollerName },
        position: { width: 420 },

        content: `<form>
            <div style="font-family:'Signika',sans-serif;">
                ${DSK_FW.UI.Header(vollerName, DSK_FW.Symbol(ahne))}
                <div class="dskbox2" style="margin-top:10px;">
                    <p style="margin:0 0 7px;">
                        Welches von <b>${casterName}</b> markierte Ziel wurde mindestens eine Aktion lang angestarrt?
                    </p>
                    <p style="font-size:.85em;color:#555;">
                        <b>Reichweite:</b> ${reichweite} Schritt ·
                        <b>Furcht:</b> ${qs} Stufe(n)
                    </p>
                    <div style="padding:8px;max-height:220px;overflow-y:auto;background:rgba(0,0,0,.04);border-radius:4px;">
                        ${auswahlHtml}
                    </div>
                </div>
            </div>
        </form>`,

        buttons: [
            {
                action: "ok",
                label: "Effekt anwenden",
                icon: "fas fa-eye",
                default: true,
                callback: event => {
                    const value = event.target.closest("form")
                        ?.querySelector('input[name="ziel"]:checked')?.value;
                    return value === undefined ? null : Number(value);
                }
            },
            {
                action: "cancel",
                label: "Abbrechen",
                icon: "fas fa-times",
                callback: () => null
            }
        ],

        rejectClose: false
    });
};

// +++ 7 - GEKOPPELTE EFFEKTE ÜBER BLOCK 6 ++++++++++++++++++++

const wendeEffekteAn = async ({
    casterActor, casterName, targetActor, targetName, qs, messageId
}) => {
    if (!casterActor || !targetActor) return false;

    const dauerKR = qs * 4;
    const linkId = `kaltes-starren-${Date.now()}-${foundry.utils.randomID()}`;

    const alteQuellen = casterActor.effects.filter(effect =>
        (effect.name || effect.label || "") === vollerName &&
        effect.getFlag("dsk", "casterUuid") === casterActor.uuid
    );

    if (alteQuellen.length) {
        await casterActor.deleteEmbeddedDocuments(
            "ActiveEffect",
            alteQuellen.map(effect => effect.id)
        );
    }

    const alteZiele = targetActor.effects.filter(effect =>
        effect.getFlag("dsk", "isKaltesStarrenZiel") === true &&
        effect.getFlag("dsk", "parentCasterUuid") === casterActor.uuid
    );

    if (alteZiele.length) {
        await targetActor.deleteEmbeddedDocuments(
            "ActiveEffect",
            alteZiele.map(effect => effect.id)
        );
    }

    let quelleffekt = null, zieleffekt = null;

    try {
        quelleffekt = await DSK_FW.Effekt.Anwenden({
            name: vollerName, ahne,
            beschreibung: beschreibungFuer(casterName, qs),
            gabeZiel: "", qs, ziel: casterActor,
            duration: {
                rounds: dauerKR,
                startTime: game.time.worldTime
            },
            showIcon: 1,
            flags: { dsk: {
                isKaltesStarrenQuelle: true,
                casterUuid: casterActor.uuid,
                qs, reichweite, kaltesStarrenLinkId: linkId,
                zielActorUuid: targetActor.uuid,
                messageId,
                wirkungsende: {
                    sfName: endeKey,
                    basisEffektName: vollerName,
                    beschreibungFuerEnde: endeText
                }
            }}
        });

        if (!quelleffekt) throw new Error("Quelleffekt fehlt.");

        zieleffekt = await DSK_FW.Effekt.Anwenden({
            name: `${vollerName} - Furcht - (${casterName})`,
            ahne,
            beschreibung:
                `Der eisige Blick von <b>${casterName}</b> erfüllt ` +
                `<b>${targetName}</b> mit <b>${qs} Stufe(n) Furcht</b>.`,
            gabeZiel: "", qs, ziel: targetActor,

            // Nur dieser Change erzeugt die Furcht.
            // Kein statuses:["feared"] und kein core.statusId.
            changes: [{
                key: "system.status.feared",
                mode: 2,
                value: String(qs),
                priority: 20
            }],

            duration: {
                rounds: dauerKR,
                startTime: game.time.worldTime
            },
            showIcon: 1,
            flags: { dsk: {
                isKaltesStarrenZiel: true,
                parentCasterUuid: casterActor.uuid,
                sourceEffectUuid: quelleffekt.uuid,
                kaltesStarrenLinkId: linkId,
                qs
            }}
        });

        if (!zieleffekt) throw new Error("Zieleffekt fehlt.");

        const furchtKorrekt = (zieleffekt.changes || []).some(change =>
            change.key === "system.status.feared" &&
            Number(change.mode) === 2 &&
            Number(change.value) === qs
        );

        const quelleKorrekt =
            quelleffekt.getFlag("dsk", "isKaltesStarrenQuelle") === true &&
            quelleffekt.getFlag("dsk", "kaltesStarrenLinkId") === linkId &&
            quelleffekt.getFlag("dsk", "zielActorUuid") === targetActor.uuid;

        const zielKorrekt =
            zieleffekt.getFlag("dsk", "isKaltesStarrenZiel") === true &&
            zieleffekt.getFlag("dsk", "parentCasterUuid") === casterActor.uuid &&
            zieleffekt.getFlag("dsk", "kaltesStarrenLinkId") === linkId &&
            !(zieleffekt.statuses?.has("feared")) &&
            furchtKorrekt;

        if (!quelleKorrekt || !zielKorrekt) {
            throw new Error("Gekoppelte Effekte unvollständig.");
        }

        await quelleffekt.update({
            "flags.dsk.zielEffektUuid": zieleffekt.uuid
        });

        return true;

    } catch (error) {
        console.error("Kaltes Starren: Effektanlage fehlgeschlagen.", {
            casterActor: casterActor.name,
            targetActor: targetActor.name,
            error
        });

        if (zieleffekt) {
            try { await zieleffekt.delete(); } catch {}
        }

        if (quelleffekt) {
            try { await quelleffekt.delete(); } catch {}
        }

        return false;
    }
};

// +++ 8 - GM-ANFRAGE VERARBEITEN +++++++++++++++++++++++++++++

const verarbeiteAnfrage = async (casterActor, daten) => {
    if (!game.user.isGM || !casterActor || !daten) return false;
    if (daten.casterUuid && daten.casterUuid !== casterActor.uuid) return false;

    if (daten.sceneId && daten.sceneId !== canvas.scene?.id) {
        ui.notifications.warn(
            `Luna sagt 🌙: Die Anfrage von „${casterActor.name}“ gehört zu einer anderen Szene.`
        );
        return false;
    }

    const casterToken = DSK_FW.Token.Finde(
        casterActor,
        daten.casterTokenId,
        daten.casterTokenUuid
    );

    if (!casterToken) return false;

    const qs = Math.max(1, Math.floor(Number(daten.qs) || 1));
    const casterName = daten.casterName || DSK_FW.ResolveTokenName(casterActor);

    const index = await frageZielAuswahl({
        ziele: daten.ziele || [],
        casterName,
        qs
    });

    if (index === null) return false;

    const zielDaten = daten.ziele?.[index];
    const { token: targetToken, actor: targetActor } = await ladeZiel(zielDaten);
    const targetName = zielDaten?.name || targetToken?.name || targetActor?.name || "Unbekanntes Ziel";
    const misserfolge = foundry.utils.deepClone(daten.misserfolge || []);

    const weiterhinGueltig = Boolean(
        targetActor &&
        targetToken &&
        targetActor.uuid !== casterActor.uuid &&
        istGueltigesZiel(targetActor) &&
        DSK_FW.Geometrie.Distanz(casterToken, targetToken) <= reichweite
    );

    const erfolgreich = weiterhinGueltig && await wendeEffekteAn({
        casterActor, casterName, targetActor, targetName,
        qs, messageId: daten.messageId
    });

    if (!erfolgreich) misserfolge.push({ name: targetName });

    await DSK_FW.GabenUI.AnfrageKarteAktualisieren({
        messageId: daten.messageId,
        gabenName: vollerName,
        ahne,
        beschreibung: daten.beschreibung,
        wirkender: casterName,
        ziele: erfolgreich
            ? [{ name: targetName, rolle: "Betroffenes Ziel" }]
            : [],
        misserfolge,
        dauerText: `${qs * 4} Kampfrunden`,
        erfolgreich
    });

    if (erfolgreich) {
        ui.notifications.info(
            `Luna sagt 🌙: ${qs} Stufe(n) Furcht auf ${targetName} angewendet.`
        );
    } else {
        ui.notifications.warn(
            "Luna sagt 🌙: Kaltes Starren konnte nicht angewendet werden."
        );
    }

    return true;
};

// +++ 9 - GM-MODUS ++++++++++++++++++++++++++++++++++++++++++++

if (game.user.isGM) {
    const anfragen = DSK_FW.GMAnfrage.Finden(flagKey);

    if (anfragen.length) {
        for (const actor of anfragen) {
            const daten = DSK_FW.GMAnfrage.Lesen(actor, flagKey);

            if (daten && await verarbeiteAnfrage(actor, daten)) {
                await DSK_FW.GMAnfrage.Loeschen(actor, flagKey);
            }
        }

        return;
    }
}

// +++ 10 - WIRKENDER UND QS +++++++++++++++++++++++++++++++++++

let casterActor = canvas.tokens.controlled[0]?.actor || game.user.character || null;

if (!casterActor) {
    casterActor =
        canvas.tokens.placeables.map(token => token.actor)
            .find(actor => actor?.getFlag("world", "letzteGabenQS") !== undefined) ||
        game.actors.find(actor =>
            actor.getFlag("world", "letzteGabenQS") !== undefined
        ) || null;
}

if (!casterActor) {
    return ui.notifications.warn("Luna sagt 🌙: Kein Wirkender gefunden!");
}

if (!game.user.isGM && !casterActor.isOwner) {
    return ui.notifications.warn(
        "Luna sagt 🌙: Du besitzt keine ausreichenden Rechte für diesen Akteur!"
    );
}

const casterToken = DSK_FW.Token.Finde(casterActor);

if (!casterToken) {
    return ui.notifications.warn(
        "Luna sagt 🌙: Der Wirkende braucht einen Token auf der aktuellen Szene!"
    );
}

const casterName = DSK_FW.ResolveTokenName(casterActor);

const qs = DSK_FW.QS.Ermitteln({
    actor: casterActor,
    gabenName,
    suchbegriffe: ["Kaltes Starren Probe", "Kaltes Starren"],
    testDataObj: typeof testData !== "undefined" ? testData : null,
    fallback: 0,
    protokollieren: true
});

if (qs <= 0) {
    await DSK_FW.GabenUI.AnfrageKarteErstellen({
        gabenName: vollerName, ahne,
        beschreibung: "Der eisige Blick konnte nicht entfesselt werden.",
        wirkender: casterName, ziele: [],
        misserfolge: [{ name: casterName }],
        dauerText: "0 Kampfrunden",
        gmBereich: false, angewendet: true, erfolgreich: false,
        anfragenderUserId: game.user.id
    });

    await raeumeQSAuf(casterActor);
    return;
}

// +++ 11 - SPIELER-TARGETS PRÜFEN +++++++++++++++++++++++++++++

const targets = Array.from(game.user.targets || []);

if (!targets.length) {
    await raeumeQSAuf(casterActor);

    return ui.notifications.warn(
        "Luna sagt 🌙: Markiere alle Ziele, die für Kaltes Starren infrage kommen!"
    );
}

const ziele = [], misserfolge = [];

for (const targetToken of targets) {
    const targetActor = targetToken?.actor;
    const targetName = targetToken?.name || targetActor?.name || "Unbekanntes Ziel";

    const gueltig = Boolean(
        targetActor &&
        targetActor.uuid !== casterActor.uuid &&
        targetActor.id !== casterActor.id &&
        istGueltigesZiel(targetActor) &&
        DSK_FW.Geometrie.Distanz(casterToken, targetToken) <= reichweite
    );

    if (!gueltig) {
        misserfolge.push({ name: targetName });
        continue;
    }

    const daten = DSK_FW.Target.Merken(targetToken);

    if (daten) ziele.push(daten);
    else misserfolge.push({ name: targetName });
}

const dauerKR = qs * 4;
const beschreibung = beschreibungFuer(casterName, qs);

if (!ziele.length) {
    await DSK_FW.GabenUI.AnfrageKarteErstellen({
        gabenName: vollerName, ahne, beschreibung,
        wirkender: casterName, ziele: [], misserfolge,
        dauerText: `${dauerKR} Kampfrunden`,
        gmBereich: false, angewendet: true, erfolgreich: false,
        anfragenderUserId: game.user.id
    });

    await raeumeQSAuf(casterActor);
    return;
}

// +++ 12 - GEMEINSAME KARTE + GM-ANFRAGE ++++++++++++++++++++++

const gmLink = DSK_FW.GabenUI.GMMakroButton(
    macroUuid,
    "Effekt anwenden",
    "Das Makro muss durch die Spielleitung ausgeführt werden."
);

const nachricht = await DSK_FW.GabenUI.AnfrageKarteErstellen({
    gabenName: vollerName, ahne, beschreibung,
    wirkender: casterName,
    ziele: ziele.map(ziel => ({
        name: ziel.name,
        rolle: "Mögliches Ziel"
    })),
    misserfolge,
    dauerText: `${dauerKR} Kampfrunden`,
    gmLink,
    gmBereich: !game.user.isGM,
    anfragenderUserId: game.user.id
});

if (!nachricht) {
    await raeumeQSAuf(casterActor);

    return ui.notifications.error(
        "Luna sagt 🌙: Die Wirkungskarte konnte nicht erstellt werden!"
    );
}

const anfrageDaten = {
    casterUuid: casterActor.uuid,
    casterName,
    casterTokenId: casterToken.id,
    casterTokenUuid:
        casterToken.document?.uuid ||
        casterToken.uuid ||
        null,
    qs,
    ziele,
    misserfolge,
    beschreibung,
    sceneId: canvas.scene?.id || null,
    messageId: nachricht.id,
    macroUuid,
    erstellt: Date.now()
};

// +++ 13 - DIREKT ODER GM-ANFRAGE +++++++++++++++++++++++++++++

if (game.user.isGM) {
    await verarbeiteAnfrage(casterActor, anfrageDaten);
    await raeumeQSAuf(casterActor);
    return;
}

await DSK_FW.GMAnfrage.Speichern(
    casterActor,
    flagKey,
    anfrageDaten
);

await raeumeQSAuf(casterActor);

ui.notifications.info(
    "Luna sagt 🌙: Kaltes Starren wurde bei der Spielleitung beantragt."
);

}).call(this);
